parameters.jsCode:
const rows = $input.all();

const STAR_KEY = "1";
const TIMESTAMP_KEY = "2026-03-13T03:26:52.607+02:00";
const BUSINESS_KEY = "Cape Town";
const REVIEWER_KEY = "Bonginkosi Kubheka";
const REVIEW_KEY = "I was not happy with the delivery of the product. Took longer than expected. Customer services was not good. ";
const RESPONSE_KEY = "Thank you, Bonginkosi Kubheka, for sharing your concerns about your recent experience with Cape Town. We apologize for the delay in delivery and the subpar customer service you received, which fell short of our standards. We will review our processes to prevent such instances in the future. We hope you will give us another chance to serve you better, and we look forward to your return.";
const TONE_KEY = "Apologetic";
const PRIORITY_KEY = "High";

const reviews = rows.map(row => {
  const d = row.json;
  return {
    timestamp:    d[TIMESTAMP_KEY] || '',
    businessName: d[BUSINESS_KEY]  || '',
    reviewerName: d[REVIEWER_KEY]  || '',
    starRating:   parseInt(d[STAR_KEY]) || 0,
    reviewText:   d[REVIEW_KEY]    || '',
    aiResponse:   d[RESPONSE_KEY]  || '',
    tone:         d[TONE_KEY]      || '',
    priority:     d[PRIORITY_KEY]  || ''
  };
});

const now = new Date();
const monthName = now.toLocaleString('en-ZA', { month: 'long' });
const year = now.getFullYear();

const total = reviews.length;
const totalReviews = total;

const ratings = reviews.map(r => r.starRating).filter(r => r > 0);
const avgRating = ratings.length
  ? (ratings.reduce((a, b) => a + b, 0) / ratings.length).toFixed(1)
  : '0.0';
const averageRating = avgRating;

const fiveStar  = ratings.filter(r => r === 5).length;
const fourStar  = ratings.filter(r => r === 4).length;
const threeStar = ratings.filter(r => r === 3).length;
const twoStar   = ratings.filter(r => r === 2).length;
const oneStar   = ratings.filter(r => r === 1).length;

const positive = reviews.filter(r =>
  (r.tone || '').toLowerCase() === 'positive'
).length;

const neutral = reviews.filter(r =>
  ['neutral', 'appreciative'].includes((r.tone || '').toLowerCase())
).length;

const negative = reviews.filter(r =>
  ['negative', 'apologetic'].includes((r.tone || '').toLowerCase())
).length;

const responseRate = total > 0
  ? ((reviews.filter(r => r.aiResponse && r.aiResponse.trim().length > 0).length / total) * 100).toFixed(0) + '%'
  : '0%';

const tones = {};
reviews.forEach(r => {
  const t = r.tone || 'Unknown';
  tones[t] = (tones[t] || 0) + 1;
});
const toneBreakdown = Object.entries(tones)
  .map(([tone, count]) => tone + ': ' + count)
  .join(' | ');

const highPriority = reviews.filter(r => (r.priority || '').toLowerCase() === 'high').length;
const medPriority  = reviews.filter(r => (r.priority || '').toLowerCase() === 'medium').length;
const lowPriority  = reviews.filter(r => (r.priority || '').toLowerCase() === 'low').length;

const businesses = {};
reviews.forEach(r => {
  const b = (r.businessName || 'Unknown').trim();
  businesses[b] = (businesses[b] || 0) + 1;
});
const topBusiness      = Object.entries(businesses).sort((a, b) => b[1] - a[1])[0];
const topBusinessName  = topBusiness ? topBusiness[0] : 'N/A';
const topBusinessCount = topBusiness ? topBusiness[1] : 0;
const businessName     = topBusinessName;

const recentSample = reviews.slice(-3).map(r =>
  r.reviewerName + ' (' + r.starRating + ' stars) said: ' + r.reviewText.substring(0, 80)
).join(' | ');

const cleanSummary = [
  'Total Reviews: ' + total,
  'Average Star Rating: ' + avgRating + ' out of 5',
  '5 Stars: ' + fiveStar + ', 4 Stars: ' + fourStar + ', 3 Stars: ' + threeStar + ', 2 Stars: ' + twoStar + ', 1 Star: ' + oneStar,
  'Tone Breakdown: ' + toneBreakdown,
  'Positive Reviews: ' + positive + ', Neutral: ' + neutral + ', Negative: ' + negative,
  'Response Rate: ' + responseRate,
  'High Priority: ' + highPriority + ', Medium Priority: ' + medPriority + ', Low Priority: ' + lowPriority,
  'Most Active Business: ' + topBusinessName + ' with ' + topBusinessCount + ' reviews',
  'Recent Reviews: ' + recentSample
].join('. ');

return [{
  json: {
    monthName,
    year,
    total,
    totalReviews,
    avgRating,
    averageRating,
    fiveStar,
    fourStar,
    threeStar,
    twoStar,
    oneStar,
    positive,
    neutral,
    negative,
    responseRate,
    toneBreakdown,
    highPriority,
    medPriority,
    lowPriority,
    topBusinessName,
    topBusinessCount,
    businessName,
    recentSample,
    summary: cleanSummary
  }
}];

